.lease-change-note,.lease-transfer-warning{grid-column:1/-1;display:grid;gap:5px;padding:11px 13px;border:1px solid #d9e3ed;border-radius:8px;background:#f6f9fc;color:#53667b;font-size:12px}.lease-change-note b{color:#12375f}.lease-transfer-warning{border-color:#efd28b;background:#fff8e7;color:#78570a}.lease-transfer-warning b{color:#8b5d00}.tenancy-actions button:first-child{background:#0b376c;color:#fff;border-color:#0b376c}.tenancy-actions button:disabled{opacity:.5;cursor:not-allowed}
</style>
